import base64
import os
from bs4 import BeautifulSoup
import requests

# 1. HTML src에 들어있던 데이터 (data:image/jpeg;base64, 뒷부분만 사용)
# 너무 길어서 생략했으니, 실제 코드에는 전체를 다 붙여넣으세요.
# base64_data = "data:image/jpeg;base64,"


def get_base64_image(base64_data):
    # 2. 바이너리로 변환하여 파일 저장
    try:
        # 쉼표(,)가 있는지 확인하고 뒷부분(순수 데이터)만 추출
        if "," in base64_data:
            pure_data = base64_data.split(",")[1]
        else:
            pure_data = base64_data

        with open("result_image.jpg", "wb") as f:
            f.write(base64.b64decode(pure_data))
        print("이미지 저장 완료!")
    except Exception as e:
        print(f"에러 발생: {e}")

def getUrlInfo_homepage1(path):
    url = path
    headers = {"User-Agent": "Mozilla/5.0"}
    response = requests.get(url, headers=headers)
    soup = BeautifulSoup(response.text, "html.parser")
    # 가장 먼저 나타나는 img 태그 하나를 찾음
    first_img = soup.find("img", class_="YQ4gaf")
    img_data = ""
    if first_img:
        src = first_img.get("src") or first_img.get("data-src")
        print(src)
        img_data = src
    return get_base64_image(img_data)